    use super::*;

    /// Generate a synthetic seismic signal with specified frequency components.
    fn make_signal(freqs: &[(f64, f64)], sample_rate: f64, duration_secs: f64) -> Vec<f64> {
        let n = (sample_rate * duration_secs) as usize;
        (0..n)
            .map(|i| {
                let t = i as f64 / sample_rate;
                freqs
                    .iter()
                    .map(|&(f, a)| a * (2.0 * PI * f * t).sin())
                    .sum::<f64>()
            })
            .collect()
    }

