    // --- FrequencyGlidingTracker tests ---

    #[test]
    fn test_gliding_upward() {
        let config = TremorConfig {
            sample_rate: 100.0,
            fft_size: 512,
            ..TremorConfig::default()
        };
        let tracker = FrequencyGlidingTracker::new(config.clone(), 5.0, 5.0);
        // Create a signal where frequency increases over time
        let duration = 60.0;
        let n = (config.sample_rate * duration) as usize;
        let mut signal = vec![0.0; n];
        for i in 0..n {
            let t = i as f64 / config.sample_rate;
            // Frequency ramps from 2 Hz to 6 Hz over 60 seconds
            let freq = 2.0 + 4.0 * t / duration;
            signal[i] = 100.0 * (2.0 * PI * freq * t).sin();
        }
        let result = tracker.track(&signal);
        assert!(!result.times.is_empty());
        assert!(!result.frequencies.is_empty());
        // Frequency should generally increase
        assert!(
            result.gliding_rate_hz_per_hour > 0.0,
            "Expected positive gliding rate, got {}",
            result.gliding_rate_hz_per_hour
        );
    }

