    #[test]
    fn test_classify_vt_event() {
        let config = TremorConfig {
            sample_rate: 100.0,
            fft_size: 512,
            ..TremorConfig::default()
        };
        let classifier = VolcanicEventClassifier::new(config.clone());
        // High-frequency impulsive signal (VT-like)
        let mut signal = vec![0.0; 500]; // 5 seconds
        // Impulsive onset with high-frequency content
        for i in 0..50 {
            let t = i as f64 / config.sample_rate;
            signal[i] = 200.0 * (-t * 10.0).exp() * (2.0 * PI * 10.0 * t).sin();
        }
        // Add high-freq content throughout
        for i in 0..500 {
            let t = i as f64 / config.sample_rate;
            signal[i] += 50.0 * (2.0 * PI * 8.0 * t).sin();
        }
        let result = classifier.classify(&signal);
        assert!(result.dominant_freq > 5.0, "Expected VT freq > 5 Hz, got {}", result.dominant_freq);
        assert!(result.peak_amplitude > 0.0);
        assert!(result.duration_secs > 0.0);
    }

